func (s *Server) importDocument(w http.ResponseWriter, r *http.Request) {
	p, _ := principalFrom(r.Context())
	all, err := s.settings.GetAll(r.Context(), false)
	if err != nil {
		writeError(w, 500, "SETTINGS_ERROR", "업로드 설정을 불러오지 못했습니다.")
		return
	}
	maxBytes := int64(all.Security.MaxUploadMB) << 20
	r.Body = http.MaxBytesReader(w, r.Body, maxBytes+(1<<20))
	if err := r.ParseMultipartForm(maxBytes); err != nil {
		writeError(w, 413, "FILE_TOO_LARGE", fmt.Sprintf("파일은 %dMB 이하여야 합니다.", all.Security.MaxUploadMB))
		return
	}
	workspaceID, err := uuid.Parse(r.FormValue("workspaceId"))
	if err != nil {
		writeError(w, 400, "WORKSPACE_REQUIRED", "워크스페이스가 필요합니다.")
		return
	}
	var memberRole, workspaceKind string
	if s.db.QueryRow(r.Context(), `SELECT wm.role,w.kind FROM workspace_members wm JOIN workspaces w ON w.id=wm.workspace_id WHERE wm.workspace_id=$1 AND wm.user_id=$2`, workspaceID, p.User.ID).Scan(&memberRole, &workspaceKind) != nil || memberRole == "VIEWER" {
		writeError(w, 403, "WORKSPACE_PERMISSION_DENIED", "이 워크스페이스로 가져올 권한이 없습니다.")
		return
	}
	var folderID *uuid.UUID
	if value := strings.TrimSpace(r.FormValue("folderId")); value != "" {
		parsed, parseErr := uuid.Parse(value)
		if parseErr != nil {
			writeError(w, 400, "INVALID_FOLDER", "폴더 식별자가 올바르지 않습니다.")
			return
		}
		var validFolder bool
		_ = s.db.QueryRow(r.Context(), `SELECT EXISTS(SELECT 1 FROM folders WHERE id=$1 AND workspace_id=$2 AND deleted_at IS NULL)`, parsed, workspaceID).Scan(&validFolder)
		if !validFolder {
			writeError(w, 400, "INVALID_FOLDER", "워크스페이스에 속한 폴더를 선택해 주세요.")
			return
		}
		folderID = &parsed
	}
	file, header, err := r.FormFile("file")
	if err != nil {
		writeError(w, 400, "FILE_REQUIRED", "가져올 파일이 필요합니다.")
		return
	}
	defer file.Close()
	body, err := io.ReadAll(io.LimitReader(file, maxBytes+1))
	if err != nil || int64(len(body)) > maxBytes {
		writeError(w, 413, "FILE_TOO_LARGE", "파일 크기 제한을 초과했습니다.")
		return
	}
	extension := strings.ToLower(filepath.Ext(header.Filename))
	if extension == "" {
		extension = extensionFromMediaType(header.Header.Get("Content-Type"), body)
	}
	documentID := uuid.New()
	parsed, err := parseUpload(r.Context(), extension, body)
	if errors.Is(err, errUnsupportedUpload) {
		writeError(w, 400, "UNSUPPORTED_IMPORT", err.Error())
		return
	}
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "파일 내용을 읽지 못했습니다: "+err.Error())
		return
	}
	content, assets, embeddedTitle, furniture := parsed.content, parsed.assets, parsed.title, parsed.furniture
	// Imported images become attachments so the editor can render them and
	// the export path can embed them again.
	attachments, content, err := prepareImportedAssets(assets, content)
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
		return
	}
	// An imported document has never been through the editor, so stamp the
	// block identities that comments, citations and diffs anchor to.
	content, err = withBlockIDs(content)
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
		return
	}
	if !validDocumentJSON(content) {
		writeError(w, 400, "IMPORT_TOO_LARGE", "가져온 문서가 너무 큽니다. 파일을 나눠서 가져와 주세요.")
		return
	}
	title := strings.TrimSpace(r.FormValue("title"))
	if title == "" {
		title = strings.TrimSpace(embeddedTitle)
	}
	if title == "" {
		title = strings.TrimSuffix(filepath.Base(header.Filename), filepath.Ext(header.Filename))
	}
	if title == "" {
		title = "가져온 문서"
	}
	title = truncateRunes(title, 240)
	// A Markdown file muni exported carries its title as the first heading;
	// now that the title is decided, that echo leaves the body — before the
	// search text is taken from it, so the title is not indexed twice.
	if parsed.markdown {
		content, err = dropLeadingTitle(content, title)
		if err != nil {
			writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
			return
		}
	}
	text := extractDocumentText(content)
	visibility := "RESTRICTED"
	if workspaceKind != "PERSONAL" {
		visibility = "WORKSPACE"
	}
	err = s.storeImportedDocument(r.Context(), importedDocument{
		id: documentID, workspaceID: workspaceID, folderID: folderID, ownerID: p.User.ID,
		title: title, visibility: visibility, content: content, text: text, furniture: furniture,
		reason: "import:" + strings.TrimPrefix(extension, "."), attachments: attachments,
	})
	if err != nil {
		writeError(w, 500, "IMPORT_FAILED", "가져온 문서를 저장하지 못했습니다.")
		return
	}
	s.audit(r, &p.User.ID, "IMPORT_DOCUMENT", "DOCUMENT", &documentID, map[string]any{"format": strings.TrimPrefix(extension, "."), "bytes": len(body), "images": len(attachments)})
	s.getDocumentByID(w, r, documentID)
}

// importedDocument is a document about to be created from a file: what the
// row needs, the reason its first revision records, and the pictures that
// become its attachments.
type importedDocument struct {
	id          uuid.UUID
	workspaceID uuid.UUID
	folderID    *uuid.UUID
	ownerID     uuid.UUID
	title       string
	visibility  string
	content     json.RawMessage
	text        string
	furniture   docx.Meta
	reason      string
	attachments []importedAttachment
}

// storeImportedDocument writes the document, its first revision and its
// attachments in one transaction, for the upload that makes a document and
// the handoff that takes one from another service.
func (s *Server) storeImportedDocument(ctx context.Context, doc importedDocument) error {
	return database.WithTx(ctx, s.db, func(tx pgx.Tx) error {
		if _, err := tx.Exec(ctx, `INSERT INTO documents(id,workspace_id,folder_id,owner_id,title,visibility,content_json,content_text,revision_no,page_header,page_footer,page_orientation) VALUES($1,$2,$3,$4,$5,$6,$7,$8,1,$9,$10,$11)`,
			doc.id, doc.workspaceID, doc.folderID, doc.ownerID, doc.title, doc.visibility, doc.content, doc.text,
			truncateRunes(doc.furniture.Header, 200), truncateRunes(doc.furniture.Footer, 200), orientationOf(doc.furniture.Landscape)); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `INSERT INTO document_revisions(document_id,revision_no,content_json,content_text,author_id,reason) VALUES($1,1,$2,$3,$4,$5)`, doc.id, doc.content, doc.text, doc.ownerID, doc.reason); err != nil {
			return err
		}
		for _, attachment := range doc.attachments {
			sum := sha256.Sum256(attachment.Data)
			if _, err := tx.Exec(ctx, `INSERT INTO attachments(id,document_id,uploader_id,name,media_type,size_bytes,sha256,data) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
				attachment.ID, doc.id, doc.ownerID, truncateRunes(attachment.Name, 240), attachment.MediaType, len(attachment.Data), hex.EncodeToString(sum[:]), attachment.Data); err != nil {
				return err
			}
		}
		return nil
	})
}

